package com.example.starter.support;

import java.time.Instant;

/**
 * 可替换的时间来源，业务一律取 UTC 瞬时值，测试可固定时钟。
 */
public interface ClockService {

    /**
     * 当前时间（UTC）。
     *
     * @return 当前瞬时
     */
    Instant now();
}

package com.example.starter.support;

import java.time.Instant;
import org.springframework.stereotype.Component;

/**
 * 系统墙钟实现，直接返回 JVM 当前 UTC 时间。
 */
@Component
public class SystemClockService implements ClockService {

    @Override
    public Instant now() {
        return Instant.now();
    }
}

package com.example.starter.web.error;

import org.springframework.http.HttpStatus;

/**
 * 业务异常基类，携带对应的 HTTP 状态码与稳定错误码。
 */
public class ApiException extends RuntimeException {

    private final HttpStatus status;
    private final String code;

    public ApiException(HttpStatus status, String code, String message) {
        super(message);
        this.status = status;
        this.code = code;
    }

    public HttpStatus getStatus() {
        return status;
    }

    public String getCode() {
        return code;
    }
}

package com.example.starter.web.error;

import org.springframework.http.HttpStatus;

/**
 * 422：请求语义可解析但业务上无法处理（读数缺失、负电量、时段不一致、超承诺上限等）。
 */
public class UnprocessableEntityException extends ApiException {

    public UnprocessableEntityException(String message) {
        super(HttpStatus.UNPROCESSABLE_ENTITY, "UNPROCESSABLE_ENTITY", message);
    }
}

package com.example.starter.web.error;

import org.springframework.http.HttpStatus;

/**
 * 409：状态冲突（时段未结束、幂等键异参重放、重复入账等）。
 */
public class ConflictException extends ApiException {

    public ConflictException(String message) {
        super(HttpStatus.CONFLICT, "CONFLICT", message);
    }
}

package com.example.starter.web.error;

import org.springframework.http.HttpStatus;

/**
 * 404：邀约等资源不存在。
 */
public class NotFoundException extends ApiException {

    public NotFoundException(String message) {
        super(HttpStatus.NOT_FOUND, "NOT_FOUND", message);
    }
}

