package com.example.starter.billing.domain;

/**
 * 读数种类：基线电量或实际电量。
 */
public enum ReadingKind {

    /** 基线电量（不参与需求响应时的预计用电量），kWh。 */
    BASELINE,

    /** 实际电量（计量表实测用电量），kWh。 */
    ACTUAL
}

package com.example.starter.billing.domain;

/**
 * 账目类型：首次结算或读数更正产生的差额结算。
 */
public enum SettlementType {

    /** 首次结算，按当时已提交的基线、实际读数版本计算。 */
    INITIAL,

    /** 更正结算，只记录新旧结果之间的差额（可为负），不覆盖首次结算。 */
    ADJUSTMENT
}

package com.example.starter.billing.domain;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 削峰邀约：调度方发布的一个左闭右开 UTC 时段。
 *
 * @param id        邀约 ID（调度方事件标识，全局唯一）
 * @param startTime 时段起点（UTC，含）
 * @param endTime   时段终点（UTC，不含）
 * @param createdAt 创建时间（UTC）
 */
public record DemandOffer(
        String id,
        Instant startTime,
        Instant endTime,
        Instant createdAt) {

    /**
     * 判断给定瞬时是否已超过时段终点。
     *
     * @param now 待判断的瞬时（UTC）
     * @return 时段已结束返回 true
     */
    public boolean isFinishedAt(Instant now) {
        return !now.isBefore(endTime);
    }

    /**
     * 判断给定左闭右开时段是否与邀约时段完全一致。
     *
     * @param start 待判断时段起点（含）
     * @param end   待判断时段终点（不含）
     * @return 完全一致返回 true
     */
    public boolean coversExactly(java.time.Instant start, java.time.Instant end) {
        return startTime.equals(start) && endTime.equals(end);
    }

    /**
     * 邀约时段长度，小时。
     *
     * @return 小时数
     */
    public BigDecimal durationHours() {
        long seconds = java.time.Duration.between(startTime, endTime).getSeconds();
        return BigDecimal.valueOf(seconds).divide(BigDecimal.valueOf(3600));
    }
}

package com.example.starter.billing.domain;

import java.math.BigDecimal;
import java.time.Instant;

/**
 * 用户对邀约的有效承诺：每个用户对每个邀约至多一条。
 *
 * @param id             承诺自增主键
 * @param offerId        邀约 ID
 * @param userId         用户 ID
 * @param committedKwh   承诺减少用电量，单位 kWh，上限 50 kWh，大于 0
 * @param requestId      承诺请求的幂等键
 * @param createdAt      创建时间（UTC）
 */
public record Commitment(
        Long id,
        String offerId,
        String userId,
        BigDecimal committedKwh,
        String requestId,
        Instant createdAt) {
}

