package com.example.starter.billing.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.time.Instant;

/**
 * 调度方发布削峰邀约请求；时段为 UTC 左闭右开。
 *
 * @param offerId   邀约 ID（调度方事件标识，全局唯一）
 * @param startTime 时段起点（UTC，含）
 * @param endTime   时段终点（UTC，不含），必须晚于起点
 */
public record CreateOfferRequest(
        @NotBlank(message = "邀约ID不能为空")
        String offerId,
        @NotNull(message = "时段起点不能为空")
        Instant startTime,
        @NotNull(message = "时段终点不能为空")
        Instant endTime) {
}

package com.example.starter.billing.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.math.BigDecimal;

/**
 * 用户承诺减量请求；每个用户对每个邀约至多一个有效承诺，承诺量上限 50 kWh。
 *
 * @param userId       用户 ID
 * @param committedKwh 承诺减少用电量，单位 kWh，(0, 50]
 * @param requestId    承诺幂等键，同参重放原结果，异参返回 409
 */
public record CreateCommitmentRequest(
        @NotBlank(message = "用户ID不能为空")
        String userId,
        @NotNull(message = "承诺电量不能为空")
        BigDecimal committedKwh,
        @NotBlank(message = "requestId不能为空")
        String requestId) {
}

package com.example.starter.billing.web.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import java.math.BigDecimal;
import java.time.Instant;

/**
 * 计量读数登记请求。读数不可变：相同 kind 再次提交即视为更正，生成版本号更大的校正记录。
 *
 * @param kind             读数种类：BASELINE 基线 / ACTUAL 实际
 * @param valueKwh         电量读数，单位 kWh，不允许为负
 * @param periodStart      计量时段起点（UTC，左闭）
 * @param periodEnd        计量时段终点（UTC，右开），必须晚于起点且与邀约时段一致
 * @param correctionReason 更正缘由；首次读数留空，更正时必填
 */
public record RegisterReadingRequest(
        @NotBlank(message = "读数种类不能为空")
        String kind,
        @NotNull(message = "电量读数不能为空")
        BigDecimal valueKwh,
        @NotNull(message = "时段起点不能为空")
        Instant periodStart,
        @NotNull(message = "时段终点不能为空")
        Instant periodEnd,
        String correctionReason) {
}

package com.example.starter.billing.web.dto;

import jakarta.validation.constraints.NotBlank;

/**
 * 结算请求。首次结算与计量更正竞争时，只取同一已提交读数版本，不拼接旧基线与新实际。
 *
 * @param requestId 结算幂等键，同参重放原结果，异参返回 409
 */
public record SettleRequest(
        @NotBlank(message = "requestId不能为空")
        String requestId) {
}

