            });
            SettlementResponse initial = settleFuture.get(30, TimeUnit.SECONDS);
            correctionFuture.get(30, TimeUnit.SECONDS);

            // 唯一一笔 INITIAL：要么用旧基线v1=30（560分），要么用新基线v2=29（480分），
