package com.example.starter.billing.bootstrap;

import com.example.starter.billing.repo.BillingRepository;
import com.example.starter.billing.domain.DemandOffer;
import java.time.Instant;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.stereotype.Component;

/**
 * 合成种子数据：调度方 18:00-19:00（UTC，左闭右开）削峰邀约。
 *
 * <p>以 UTC {@link Instant} 参数绑定幂等写入，规避 SQL 时间字面量随 JVM 时区漂移；
 * H2 内存库每次启动重建，本地运行与标准 test 均能看到该邀约。</p>
 */
@Component
public class SyntheticDataSeeder implements ApplicationRunner {

    /** 合成邀约 ID。 */
    public static final String SEED_OFFER_ID = "offer-20261001-1800";

    private static final Instant WINDOW_START = Instant.parse("2026-10-01T18:00:00Z");
    private static final Instant WINDOW_END = Instant.parse("2026-10-01T19:00:00Z");
    private static final Instant PUBLISHED_AT = Instant.parse("2026-10-01T10:00:00Z");

    private static final Logger log = LoggerFactory.getLogger(SyntheticDataSeeder.class);

    private final BillingRepository repository;

    public SyntheticDataSeeder(BillingRepository repository) {
        this.repository = repository;
    }

    @Override
    public void run(ApplicationArguments args) {
        if (repository.findOffer(SEED_OFFER_ID) == null) {
            repository.insertOffer(new DemandOffer(
                    SEED_OFFER_ID, WINDOW_START, WINDOW_END, PUBLISHED_AT));
            log.info("已写入合成种子邀约 {} ({}-{} UTC，左闭右开)",
                    SEED_OFFER_ID, WINDOW_START, WINDOW_END);
        }
    }
}

