import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

/**
 * 校验 data.sql 合成种子邀约已随上下文启动自动写入 H2（MODE=MySQL）。
 */
@SpringBootTest
class SeedDataTest {

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @Test
    @DisplayName("种子数据：18:00-19:00（UTC左闭右开）削峰邀约存在")
    void seedOfferExists() {
        Integer count = jdbcTemplate.queryForObject(
                "SELECT COUNT(1) FROM demand_offer WHERE id = 'offer-20261001-1800'",
                Integer.class);
        assertEquals(1, count);
        assertEquals(Instant.parse("2026-10-01T18:00:00Z"),
                jdbcTemplate.queryForObject(
                        "SELECT start_time FROM demand_offer WHERE id = 'offer-20261001-1800'",
                        java.sql.Timestamp.class).toInstant());
        assertEquals(Instant.parse("2026-10-01T19:00:00Z"),
                jdbcTemplate.queryForObject(
                        "SELECT end_time FROM demand_offer WHERE id = 'offer-20261001-1800'",
                        java.sql.Timestamp.class).toInstant());
    }
}
